/* Все главы подряд (для совместимости: LAB.guide.chapters). */
var CH = [];
SEC.forEach(function (s) { (s.ch || []).forEach(function (c) { CH.push(c); }); });
TOUCH.forEach(function (c) { CH.push({ t: c.t, x: c.x, touch: true }); });

function paras(c) { return (c.xf ? c.xf() : c.x).filter(function (p) { return !(p && p.desk) || LAB.desktop; }); }
function txt(c) { return paras(c).map(function (p) { return typeof p === "string" ? p : p.desk ? p.x : LAB.K(p[0], p[1]); }).join(" "); }
/* Главы раздела: «Управление» — жесты или клавиши; прочие — кроме ещё закрытых. */
function chaptersOf(s) {
  if (s.ctl) return LAB.kb() ? KB.filter(function (c) { return !c.desk || LAB.desktop; }) : TOUCH;
  return s.ch.filter(function (c) { return !c.when || c.when(); });
}
function section(s) {
  var back = function () { section(s); };
  LAB.ui.menu(s.t, chaptersOf(s).map(function (c) {
    return { label: c.t, fn: function () { LAB.ui.note(c.t, txt(c), back); } };
  }).concat([{ label: "Назад", fn: open }]));
}
function keyboard() {
  section({ t: "Клавиатура", ctl: true });
}
function refs() {
  LAB.ui.menu("Справочники", [
    { label: "Бестиарий: мутанты и роботы", fn: bestiary },
    { label: "Гербарий: растения и плоды", fn: function () { if (LAB.plants) LAB.plants.herbarium(refs); } }, /* (после 4.0) */
    { label: "Оружие", fn: weapons },
    { label: "Броня", fn: armors },
    { label: "Назад", fn: open }
  ]);
}

function open() {
  /* руководство открыли посреди чтения (F1 на главе или записке) — чтение
     обрывается, окно записки закрывается: иначе меню молчит, пока дочитывается текст */
  var tp = LAB.ui.top && LAB.ui.top();
  if (tp && tp.note) LAB.ui.closeTop(true);
  if (LAB.Speech.noteReading) LAB.Speech.endNote();
  var items = SEC.map(function (s) {
    return { label: s.ctl ? (LAB.kb() ? "Управление: клавиатура" : "Управление: жесты") : s.t, fn: function () { section(s); } };
  });
  LAB.ui.menu("Руководство", items.concat([
    { label: "Справочники: бестиарий, гербарий, оружие, броня", fn: refs },
    { label: "Что нового?", fn: function () { if (LAB.news) LAB.news.open(open); } },
    { label: "Назад", fn: function () {} }
  ]));
}
