/* Сколько уровней игрок уже видел: в справочниках — только то, что встречается до этой глубины. */
function reachL() { var g = LAB.game && LAB.game.G; return Math.max(10, (LAB.game && LAB.game.entered && g && g.L) || 1); }
var foeL = null;
function foeDepth(id) {
  if (!foeL) { foeL = {}; for (var L = 1; L < LAB.LEVELS.length; L++) { var lv = LAB.LEVELS[L]; if (!lv) continue; lv.foes.forEach(function (f) { if (!foeL[f]) foeL[f] = L; }); if (LAB.BOSSES[lv.boss] && !foeL["boss:" + lv.boss]) foeL["boss:" + lv.boss] = L; } }
  /* (2.5) матки и прочие, кто бывает только в отрядах, — с глубины своего отряда */
  var b = LAB.FOES[id];
  return foeL[id] || (b && b.lv ? b.lv[0] : 1);
}
function foeNote(ff, back) {
  var nat = LAB.mutants && ff.kind === "bio" ? LAB.mutants.natureLine(ff) : "";
  /* (3.7, нелогичность) чем бить — по стойкостям самого вида (combat.js, weakness: природа и его res):
     прежде каждому роботу — «ионы, электрошок и ЭМИ», даже Глубиннику, которого ЭМИ почти не берёт,
     каждой твари — «плазма и жар», даже Термофилу, который жар только пьёт */
  var and = function (a) { return a.length > 1 ? a.slice(0, -1).join(", ") + " и " + a[a.length - 1] : a[0]; };
  var w = LAB.combat && LAB.combat.weakness ? LAB.combat.weakness(ff) : null;
  var tip = w ? (w.bestN.length ? "Лучше всего берут: " + and(w.bestN) + "." : "Особых слабостей нет.") + (w.worstN.length ? " Почти не берут: " + and(w.worstN) + "." : "")
    : ff.kind === "mech" ? "Ионы, электрошок и ЭМИ — лучшее против него." : ff.kind === "anom" ? "Обычное оружие его почти не берёт: нужны позитроны, звук, фаза или гравитация." : "Магнетрон, плазма и жар — лучшее против него.";
  LAB.ui.note(ff.n, (nat ? cap(nat) + ". " : "") + ff.desc + " Удар: " + LAB.ATK_T[ff.adt || "phys"] + ". " + tip, back);
}
function cap(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
/* (2.5) Твари — по семействам: в каждом — вид, ум, ранг и каста. */
function mutantsMenu() {
  var maxL = reachL(), fams = {}, order = [];
  for (var id in LAB.FOES) {
    var f = LAB.FOES[id];
    if (f.kind !== "bio" || foeDepth(id) > maxL) continue;
    var fam = f.fam || "Прочие твари";
    if (!fams[fam]) { fams[fam] = []; order.push(fam); }
    fams[fam].push(f);
  }
  var items = order.map(function (fam) {
    return { label: fam + ": " + fams[fam].length, fn: function () {
      var list = fams[fam].map(function (ff) {
        var nat = LAB.mutants ? LAB.mutants.natureLine(ff) : "";
        return { label: ff.n + (nat ? ", " + nat.split(", ").slice(0, 2).join(", ") : ""), fn: function () { foeNote(ff, mutantsMenu); } };
      });
      list.push({ label: "Назад", fn: mutantsMenu });
      LAB.ui.menu(fam, list);
    } };
  });
  items.push({ label: "Как живут твари: ум, касты, отряды, развитие", fn: function () {
    LAB.ui.note("Как живут твари", MUT_LIFE, mutantsMenu);
  } });
  items.push({ label: "Назад", fn: bestiary });
  LAB.ui.menu("Мутанты", items);
}
function bestiary() {
  var items = [], maxL = reachL();
  var nb = 0; for (var bid in LAB.FOES) if (LAB.FOES[bid].kind === "bio" && foeDepth(bid) <= maxL) nb++;
  items.push({ label: "Мутанты по семействам: " + nb + " " + (LAB.game && LAB.game.plural ? LAB.game.plural(nb, "вид", "вида", "видов") : "видов"), fn: mutantsMenu });
  ["mech", "anom"].forEach(function (kind) {
    for (var id in LAB.FOES) {
      var f = LAB.FOES[id];
      if (f.kind !== kind || foeDepth(id) > maxL) continue;
      items.push({ label: (kind === "mech" ? "Робот: " : "Аномалия: ") + f.n, fn: (function (ff) { return function () { foeNote(ff, bestiary); }; })(f) });
    }
  });
  items.push({ label: "Модификации роботов", fn: function () {
    var t = []; for (var k in LAB.AFFIX) t.push(LAB.AFFIX[k].m + " — " + LAB.AFFIX[k].desc);
    LAB.ui.note("Модификации роботов", "Чем глубже, тем чаще роботы выходят с модификациями. " + t.join(". ") + ".", bestiary);
  } });
  items.push({ label: "Стражи шлюзов", fn: function () {
    var t = [], maxL = reachL(); for (var k in LAB.BOSSES) if (foeDepth("boss:" + k) <= maxL) t.push(LAB.BOSSES[k].n + ": " + LAB.BOSSES[k].desc);
    LAB.ui.note("Стражи", t.join(" "), bestiary);
  } });
  items.push({ label: "Назад", fn: refs });
  LAB.ui.menu("Бестиарий", items);
}
function weapons() {
  var items = [];
  var maxL = reachL();
  for (var id in LAB.WEAPONS) {
    var w = LAB.WEAPONS[id];
    if ((LAB.WEAPON_DEPTH[id] || 1) > maxL) continue;
    items.push({ label: w.n.charAt(0).toUpperCase() + w.n.slice(1) + ", с уровня " + (LAB.WEAPON_DEPTH[id] || 1), fn: (function (ww) { return function () { LAB.ui.note(ww.n, ww.desc + " Урон — " + LAB.DTYPE_N[ww.dt] + ", дальность " + ww.rng + (ww.ammo !== "none" ? ", питание — " + LAB.AMMO[ww.ammo].n.toLowerCase() : ", без батарей") + ".", weapons); }; })(w) });
  }
  items.push({ label: "Назад", fn: refs });
  LAB.ui.menu("Справочник: оружие", items); /* своё название: «Оружие» — окно инвентаря, одинаковое закрыло бы его */
}
function armors() {
  var items = [];
  var maxL = reachL();
  for (var id in LAB.ARMORS) {
    var a = LAB.ARMORS[id];
    if (a.depth > maxL) continue;
    items.push({ label: a.n.charAt(0).toUpperCase() + a.n.slice(1) + ", с уровня " + a.depth, fn: (function (aa) { return function () {
      var r = []; for (var t in aa.res) r.push(LAB.ATK_T[t] + " " + Math.round(aa.res[t] * 100) + "%");
      LAB.ui.note(aa.n, aa.desc + " Защита " + aa.def + " на первом уровне, глубже — больше. Стойкость: " + (r.join(", ") || "нет") + "." + (aa.special ? " Особенность: " + LAB.ARMOR_SPECIAL[aa.special] + "." : ""), armors);
    }; })(a) });
  }
  items.push({ label: "Назад", fn: refs });
  LAB.ui.menu("Справочник: броня", items);
}

LAB.guide = { open: open, keyboard: keyboard, chapters: CH, keys: KB, sections: SEC, touch: TOUCH, section: section };
